local LAUNCHER_TEMPLATE = [[
/* Generated by Projectum Lunare Forge - LÖVE Game Launcher */
#include <cstdio>
#include <cstdlib>
#include <cstring>

#ifdef __cplusplus
extern "C" {
#endif
#if defined(FORGE_LUA_SUBDIR)
#  include <lua/lua.h>
#  include <lua/lauxlib.h>
#  include <lua/lualib.h>
#else
#  include <lua.h>
#  include <lauxlib.h>
#  include <lualib.h>
#endif

int luaopen_love(lua_State *L);
const char *love_version();
const char *love_codename();

<% for _, mod in ipairs(native_modules or {}) do %>
int <%= mod.symbol %>(lua_State *L);
<% end %>

#ifdef __cplusplus
}
#endif

static int love_preload(lua_State *L, lua_CFunction f, const char *name) {
    lua_getglobal(L, "package");
    lua_getfield(L, -1, "preload");
    lua_pushcfunction(L, f);
    lua_setfield(L, -2, name);
    lua_pop(L, 2);
    return 0;
}

static int luax_resume(lua_State *L, int nargs, int *nres) {
#if LUA_VERSION_NUM >= 504
    return lua_resume(L, NULL, nargs, nres);
#elif LUA_VERSION_NUM >= 502
    (void)nres;
    return lua_resume(L, NULL, nargs);
#else
    (void)nres;
    return lua_resume(L, nargs);
#endif
}

int main(int argc, char **argv) {
    if (argc > 1 && strcmp(argv[1], "--version") == 0) {
        printf("LOVE %s (%s) [Forge Powered]\n", love_version(), love_codename());
        return 0;
    }

    lua_State *L = luaL_newstate();
    if (!L) {
        fprintf(stderr, "[forge.love] Error: Failed to initialize Lua runtime.\n");
        return 1;
    }
    luaL_openlibs(L);

    /* Preload native C extensions */
<% for _, mod in ipairs(native_modules or {}) do %>
    love_preload(L, <%= mod.symbol %>, "<%= mod.name %>");
<% end %>

    /* Preload LÖVE */
    love_preload(L, luaopen_love, "love");

    /* Populate arg table */
    lua_newtable(L);
    for (int i = 0; i < argc; i++) {
        lua_pushstring(L, argv[i]);
        lua_rawseti(L, -2, i);
    }
    lua_setglobal(L, "arg");

    /* require "love" */
    lua_getglobal(L, "require");
    lua_pushstring(L, "love");
    lua_call(L, 1, 1);
    lua_pushboolean(L, 1);
    lua_setfield(L, -2, "_exe");
    lua_pop(L, 1);

    /* require "love.boot" */
    lua_getglobal(L, "require");
    lua_pushstring(L, "love.boot");
    lua_call(L, 1, 1);

    /* Run boot coroutine */
    lua_newthread(L);
    lua_pushvalue(L, -2);
    int stackpos = lua_gettop(L);
    int nres = 0;
    while (luax_resume(L, 0, &nres) == LUA_YIELD) {
#if LUA_VERSION_NUM >= 504
        lua_pop(L, nres);
#else
        lua_pop(L, lua_gettop(L) - stackpos);
#endif
    }

    int retval = 0;
    if (lua_isnumber(L, -1))
        retval = (int)lua_tonumber(L, -1);

    lua_close(L);
    return retval;
}
]]

local function find_game_dir(target)
    local explicit = target:values("love.dir") or target:values("forge.love.dir")
    if explicit then
        return path.is_absolute(explicit) and explicit or path.join(os.projectdir(), explicit)
    end

    -- Look for main.lua in target files or project dirs
    for _, f in ipairs(table.wrap(target:get("files"))) do
        if f:endswith("main.lua") then
            local dir = path.directory(f)
            return path.is_absolute(dir) and dir or path.join(os.projectdir(), dir)
        end
    end

    if os.isfile(path.join(os.projectdir(), "src", "main.lua")) then
        return path.join(os.projectdir(), "src")
    end
    if os.isfile(path.join(os.projectdir(), "main.lua")) then
        return os.projectdir()
    end

    return path.join(os.projectdir(), "src")
end

local function get_native_modules(target, lua_module)
    local modules = {}
    local seen = {}

    -- 1. Discover dynamically via Forge's Lua module tree and package manifests
    if lua_module and lua_module.roots_of and lua_module.bundle_sources then
        local roots = lua_module.roots_of(target)
        local bundled = lua_module.bundle_sources(roots)
        for _, native in ipairs(bundled.natives or {}) do
            if native.name and native.symbol and not seen[native.name] then
                seen[native.name] = true
                table.insert(modules, {
                    name = native.name,
                    symbol = native.symbol
                })
            end
        end
    end

    -- 2. User-declared custom modules via target:values("love.modules") or target:values("forge.love.modules")
    local custom = target:values("love.modules") or target:values("forge.love.modules")
    if custom then
        for _, mod in ipairs(table.wrap(custom)) do
            local name = mod.name
            local symbol = mod.symbol or (lua_module and lua_module.open_symbol and lua_module.open_symbol(name)) or ("luaopen_" .. name:gsub("[^%w]", "_"))
            if name and not seen[name] then
                seen[name] = true
                table.insert(modules, {name = name, symbol = symbol})
            end
        end
    end

    return modules
end

local function setup_love_rule(rule_name)
    rule(rule_name)
        add_deps("c++")
        set_extensions(".lua")

        on_load(function (target)
            target:set("kind", "binary")
            target:set("languages", "c++11")

            -- Ensure love package is included
            local has_love = false
            for _, pkg in ipairs(table.wrap(target:get("packages"))) do
                if pkg == "love" or pkg:startswith("love ") then
                    has_love = true
                    break
                end
            end
            if not has_love then
                target:add("packages", "love")
            end

            -- POSIX system libraries
            if not target:is_plat("windows", "mingw", "dos", "os2") then
                target:add("syslinks", "m", "dl", "pthread")
            end

            -- Tag lua and asset files so standard C++ compiler does not try to compile them directly
            for _, sourcefile in ipairs(table.wrap(target:get("files"))) do
                if sourcefile:endswith(".lua") or not (sourcefile:endswith(".cpp") or sourcefile:endswith(".c") or sourcefile:endswith(".cc")) then
                    target:fileconfig_set(sourcefile, {rules = rule_name})
                end
            end
        end)

        before_buildcmd_files(function (target, batchcmds, sourcebatch, opt)
            import("template", {rootdir = path.join(os.scriptdir(), "../../../modules")})
            local lua_module = import("lua.module", {anonymous = true})

            local native_modules = get_native_modules(target, lua_module)
            local render = template.compile(LAUNCHER_TEMPLATE)
            local content = render({native_modules = native_modules})

            local launcher_cpp = path.join(target:autogendir(), "love_launcher.cpp")
            local old_content = os.isfile(launcher_cpp) and io.readfile(launcher_cpp) or nil
            if old_content ~= content then
                io.writefile(launcher_cpp, content)
            end

            local objfile = target:objectfile(launcher_cpp)
            table.insert(target:objectfiles(), objfile)

            batchcmds:mkdir(path.directory(launcher_cpp))
            batchcmds:mkdir(path.directory(objfile))
            batchcmds:show_progress(opt.progress, "${color.build.target}compiling.love_launcher %s", path.relative(launcher_cpp, os.projectdir()))
            batchcmds:compile(launcher_cpp, objfile)
            batchcmds:add_depfiles(sourcebatch.sourcefiles)
            batchcmds:set_depmtime(os.mtime(objfile))
            batchcmds:set_depcache(target:dependfile(objfile))
        end)

        after_build(function (target)
            import("utils.archive")

            local is_fused = target:values("love.fused")
            if is_fused == nil then
                is_fused = is_mode("release")
            end

            if not is_fused then
                return
            end

            local gamedir = find_game_dir(target)
            if not os.isdir(gamedir) and not os.isfile(path.join(gamedir, "main.lua")) then
                return
            end

            local targetfile = target:targetfile()
            if not os.isfile(targetfile) then
                return
            end

            -- Pack game files and bundled Lua modules into a temporary zip
            local temp_zip = path.absolute(path.join(target:autogendir(), "game_bundle.zip"))
            local stage_dir = path.absolute(path.join(target:autogendir(), "game_stage"))
            os.rm(temp_zip)
            os.rm(stage_dir)
            os.mkdir(stage_dir)
            os.cp(path.join(gamedir, "*"), stage_dir)

            local lua_module = import("lua.module", {anonymous = true})
            if lua_module and lua_module.roots_of and lua_module.bundle_sources then
                local roots = lua_module.roots_of(target)
                local bundled = lua_module.bundle_sources(roots)
                for abs, rel in pairs(bundled.file_map or {}) do
                    local dst = path.join(stage_dir, rel)
                    if not os.isfile(dst) then
                        os.mkdir(path.directory(dst))
                        os.cp(abs, dst)
                    end
                end
            end

            local err
            local ok = try {
                function ()
                    archive.archive(temp_zip, ".", {curdir = stage_dir, recurse = true})
                    return true
                end,
                catch {
                    function (errors)
                        err = errors
                    end
                }
            }

            os.rm(stage_dir)

            if not (ok and os.isfile(temp_zip)) then
                raise("failed to pack game assets into zip bundle: %s", err or "unknown error")
            end

            local bin_data = io.readfile(targetfile, {encoding = "binary"})
            local zip_data = io.readfile(temp_zip, {encoding = "binary"})
            io.writefile(targetfile, bin_data .. zip_data, {encoding = "binary"})
            os.rm(temp_zip)

            if not target:is_plat("windows") then
                try { function () os.runv("chmod", {"+x", targetfile}) end }
            end
            cprint("${green}[forge.love] Fused standalone game binary generated: %s${clear}", targetfile)
        end)

        on_run(function (target)
            import("core.base.option")

            local targetfile = target:targetfile()
            local args = option.get("arguments") or {}

            local is_fused = target:values("love.fused")
            if is_fused == nil then
                is_fused = is_mode("release")
            end

            if is_fused then
                os.execv(targetfile, args)
            else
                local gamedir = find_game_dir(target)
                local run_args = table.join({gamedir}, args)
                cprint("${dim}==> [forge.love] Running: %s %s${clear}", targetfile, table.concat(run_args, " "))

                local run_envs = {}
                local lua_module = import("lua.module", {anonymous = true})
                if lua_module and lua_module.roots_of and lua_module.search_patterns then
                    local roots = lua_module.roots_of(target)
                    local patterns = lua_module.search_patterns(roots, "path")
                    if #patterns > 0 then
                        local cur_path = os.getenv("LUA_PATH") or ""
                        run_envs.LUA_PATH = table.concat(patterns, ";") .. (cur_path ~= "" and (";" .. cur_path) or ";;")
                    end
                end

                os.execv(targetfile, run_args, {envs = run_envs})
            end
        end)
end

setup_love_rule("forge.engine.love")
